Using Convex 1.44.0, two different uploaded files, A and B, are initially downloadable. Each has its own `files` row with `storageId: v.id("_storage")`; each saved download URL came from `ctx.storage.getUrl`. Immediately after setup, call `removeRow` with A's `fileId`, then, after it completes, call `removeObject` with B's `fileId`. Make the fresh GET in the question immediately after those calls. No other code changes either file.

```ts
import { v } from "convex/values";
import { mutation } from "./_generated/server";

export const removeRow = mutation({
  args: { fileId: v.id("files") },
  handler: async (ctx, { fileId }) => {
    await ctx.db.delete("files", fileId);
  },
});

export const removeObject = mutation({
  args: { fileId: v.id("files") },
  handler: async (ctx, { fileId }) => {
    const file = await ctx.db.get("files", fileId);
    if (!file) throw new Error("File not found");
    await ctx.storage.delete(file.storageId);
  },
});
```
